static uint8_t captured_frame[APP_OLED_FRAMEBUFFER_BYTES];
static size_t captured_frame_length;
static UART_HandleTypeDef *fake_uart_handle;

UART_HandleTypeDef *firmgen_uart_handle(void)
{
    return fake_uart_handle;
}

static oled_port_status_t record_oled_write(uint8_t address_7bit,
                                             uint8_t control_byte,
                                             const uint8_t *data,
                                             size_t length,
                                             int cmock_num_calls)
{
    (void)address_7bit;
    (void)cmock_num_calls;

    if ((control_byte == APP_OLED_DATA_CONTROL_BYTE) &&
        (data != NULL) &&
        (captured_frame_length + length <= sizeof(captured_frame)))
    {
        memcpy(&captured_frame[captured_frame_length], data, length);
        captured_frame_length += length;
    }

    return (oled_port_status_t)0;
}

void setUp(void)
{
    memset(captured_frame, 0, sizeof(captured_frame));
    captured_frame_length = 0U;
    fake_uart_handle = NULL;
}

