{
}

void test_FR_011_01(void)
{
    oled_service_state_t state = {0};
    oled_dashboard_data_t data = {0};
    sh1106_t expected_display;
    oled_service_status_t status;

    memset(&expected_display, 0, sizeof(expected_display));
    expected_display.is_initialized = true;

    TEST_ASSERT_EQUAL_INT(SH1106_STATUS_OK,
                          sh1106_draw_text(&expected_display, 0U, 0U,
                                           "Vehicle Parameters"));
    TEST_ASSERT_EQUAL_INT(SH1106_STATUS_OK,
                          sh1106_draw_text(&expected_display, 1U, 0U,
                                           "Display"));

    data.active_event = MOTION_EVENT_NONE;
    oled_port_write_StubWithCallback(record_oled_write);
    motion_processor_event_name_IgnoreAndReturn("");

    status = oled_service_refresh(&state, &data, 0U);
    TEST_ASSERT_EQUAL_INT(OLED_SERVICE_STATUS_OK, status);

    for (uint32_t now_ms = APP_OLED_REFRESH_INTERVAL_MS;
         (now_ms <= (100U * APP_OLED_REFRESH_INTERVAL_MS)) &&
         state.has_pending_frame;
         now_ms += APP_OLED_REFRESH_INTERVAL_MS)
    {
        (void)oled_service_refresh(&state, &data, now_ms);
    }

    TEST_ASSERT_EQUAL_INT(APP_OLED_FRAMEBUFFER_BYTES, captured_frame_length);
    TEST_ASSERT_EQUAL_MEMORY(expected_display.framebuffer,
                             captured_frame,
                             APP_OLED_WIDTH_PIXELS);
    TEST_ASSERT_EQUAL_MEMORY(expected_display.framebuffer + APP_OLED_WIDTH_PIXELS,
                             captured_frame + APP_OLED_WIDTH_PIXELS,
                             APP_OLED_WIDTH_PIXELS);
}
